// Package emit generates the host role files (agents/ and adapters/<host>/)
// from the neutral definitions in core/roles/. It is a port of
// the 1.x bin/build-adapters.sh; the committed generated files are the oracle.
package emit

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const preamble = "`<project-dir>` below is the directory that holds `sdkit.env`: `.sdkit/` (a repo set up before 1.0 may still use `.agentkit/`, `.claude/` or `.codex/` with `project.env`; the handoff names it)."

// Dirs are the generated trees compared by Check, relative to the kit root.
var Dirs = []string{"agents", "adapters/codex", "adapters/opencode/agents", "adapters/cursor/agents", "adapters/gemini/agents"}

// Role is one subagent definition (front matter plus body) at one tier.
type Role struct {
	Name, Desc, Access, Tier string
	Independent, RO          bool
	Body, Note               string
}

// Settings is core/tiers.env and core/hosts.env merged.
type Settings map[string]string

func parseEnv(s Settings, data string) {
	for _, line := range strings.Split(data, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		v = strings.TrimSpace(v)
		if strings.HasPrefix(v, `"`) {
			if i := strings.Index(v[1:], `"`); i >= 0 {
				v = v[1 : 1+i]
			}
		} else if i := strings.Index(v, " #"); i >= 0 {
			v = strings.TrimSpace(v[:i])
		}
		s[k] = v
	}
}

// field returns the first value of key in the front matter, like the awk.
func field(lines []string, key string) string {
	f := 0
	for _, l := range lines {
		if l == "---" {
			f++
			continue
		}
		if f == 1 && strings.HasPrefix(l, key+":") {
			return strings.TrimLeft(l[len(key)+1:], " ")
		}
	}
	return ""
}

// body is every line after the closing marker, except lines that are "---".
func body(lines []string) string {
	var b strings.Builder
	f := 0
	for _, l := range lines {
		if l == "---" {
			f++
			continue
		}
		if f >= 2 {
			b.WriteString(l + "\n")
		}
	}
	return b.String()
}

func esc(s string) string {
	return strings.ReplaceAll(strings.ReplaceAll(s, `\`, `\\`), `"`, `\"`)
}

// Build renders every generated file as relative path -> content.
func Build(root string) (map[string]string, int, error) {
	set := Settings{}
	for _, n := range []string{"tiers.env", "hosts.env"} {
		b, err := os.ReadFile(filepath.Join(root, "core", n))
		if err != nil {
			return nil, 0, err
		}
		parseEnv(set, string(b))
	}
	files, err := filepath.Glob(filepath.Join(root, "core", "roles", "*.md"))
	if err != nil {
		return nil, 0, err
	}
	sort.Strings(files)
	out := map[string]string{}
	var snippet strings.Builder
	snippet.WriteString("# Merge into .codex/config.toml (project) or ~/.codex/config.toml. Generated by sdkit dev adapters; do not edit.\n" +
		"# Role files live next to config.toml under agents/. Multi-agent must be enabled in your Codex version.\n\n" +
		"[agents]\nmax_concurrent_threads_per_session = 3   # parallel subagents multiply token use; raise deliberately\n")
	count := 0
	for _, f := range files {
		if filepath.Base(f) == "README.md" {
			continue
		}
		data, err := os.ReadFile(f)
		if err != nil {
			return nil, 0, err
		}
		text := string(data)
		text = strings.TrimSuffix(text, "\n")
		lines := strings.Split(text, "\n")
		name, desc, kind := field(lines, "name"), field(lines, "description"), field(lines, "kind")
		access, tier, deep := field(lines, "access"), field(lines, "tier"), field(lines, "deep")
		if name == "" || desc == "" || access == "" || tier == "" {
			return nil, 0, fmt.Errorf("bad frontmatter: %s", f)
		}
		if kind != "subagent" {
			continue
		}
		for _, t := range strings.Fields(tier + " " + deep) {
			if t != "light" && t != "standard" && t != "strong" {
				return nil, 0, fmt.Errorf("bad tier '%s' in %s", t, f)
			}
		}
		ro := false
		switch access {
		case "read-only":
			ro = true
		case "docs", "tests", "code", "infra":
		default:
			return nil, 0, fmt.Errorf("bad access '%s' in %s", access, f)
		}
		note := "Generated from core/roles/" + name + ".md by sdkit dev adapters; edit the source."
		indep := field(lines, "independent") == "true"
		if indep {
			note += " Independent role: never give it the implementer's reasoning."
		}
		r := Role{Name: name, Desc: desc, Access: access, Tier: strings.ToUpper(tier), Independent: indep, RO: ro, Body: body(lines), Note: note}
		variants := []Role{r}
		if deep != "" {
			d := r
			d.Name, d.Desc, d.Tier = name+"-deep", desc+" Strong-tier variant for high-risk work.", strings.ToUpper(deep)
			variants = append(variants, d)
		}
		for _, v := range variants {
			if err := roleFiles(v, set, out, &snippet); err != nil {
				return nil, 0, err
			}
			count++
		}
	}
	out["adapters/codex/config.toml.snippet"] = snippet.String()
	return out, count, nil
}

func roleFiles(r Role, s Settings, out map[string]string, snippet *strings.Builder) error {
	head := "<!-- " + r.Note + " -->\n" + preamble + "\n" + r.Body
	// Claude Code
	tools := "Read, Grep, Glob, Bash"
	if !r.RO {
		tools += ", Edit, Write"
	}
	out["agents/"+r.Name+".md"] = fmt.Sprintf("---\nname: %s\ndescription: %s\ntools: %s\nmodel: %s\n---\n", r.Name, r.Desc, tools, s["CLAUDE_MODEL_"+r.Tier]) + head
	// Codex
	if strings.Contains(r.Body, "'''") {
		return fmt.Errorf("role %s contains ''' which breaks the TOML literal string", r.Name)
	}
	sandbox := "read-only"
	if !r.RO {
		sandbox = "workspace-write"
	}
	var c strings.Builder
	c.WriteString("# " + r.Note + "\n")
	if m := s["CODEX_MODEL_"+r.Tier]; m != "" {
		c.WriteString("model = \"" + m + "\"\n")
	}
	c.WriteString("model_reasoning_effort = \"" + s["CODEX_EFFORT_"+r.Tier] + "\"\nsandbox_mode = \"" + sandbox + "\"\ndeveloper_instructions = '''\n" + preamble + "\n" + r.Body + "'''\n")
	out["adapters/codex/agents/"+r.Name+".toml"] = c.String()
	snippet.WriteString("\n[agents." + r.Name + "]\ndescription = \"" + esc(r.Desc) + "\"\nconfig_file = \"agents/" + r.Name + ".toml\"\n")
	// Cursor
	model := s["CURSOR_MODEL_"+r.Tier]
	if model == "" {
		model = "inherit"
	}
	out["adapters/cursor/agents/"+r.Name+".md"] = fmt.Sprintf("---\nname: %s\ndescription: \"%s\"\nmodel: %s\nreadonly: %t\n---\n", r.Name, esc(r.Desc), model, r.RO) + head
	// Gemini
	tl := s["GEMINI_TOOLS_READ"]
	if !r.RO {
		tl += ", " + s["GEMINI_TOOLS_WRITE"]
	}
	var g strings.Builder
	fmt.Fprintf(&g, "---\nname: %s\ndescription: \"%s\"\ntools:\n", r.Name, esc(r.Desc))
	for _, t := range strings.Split(strings.ReplaceAll(tl, " ", ""), ",") {
		if t != "" {
			g.WriteString("  - " + t + "\n")
		}
	}
	if m := s["GEMINI_MODEL_"+r.Tier]; m != "" {
		g.WriteString("model: " + m + "\n")
	}
	g.WriteString("---\n" + head)
	out["adapters/gemini/agents/"+r.Name+".md"] = g.String()
	// OpenCode
	var o strings.Builder
	fmt.Fprintf(&o, "---\ndescription: \"%s\"\nmode: subagent\n", esc(r.Desc))
	if m := s["OPENCODE_MODEL_"+r.Tier]; m != "" {
		o.WriteString("model: " + m + "\n")
	}
	if r.RO {
		fmt.Fprintf(&o, "permission:\n  edit: deny\n  %s:\n    \"*\": deny\n", s["OPENCODE_SHELL_KEY"])
		for _, p := range strings.Split(s["READONLY_SHELL_ALLOW"], "|") {
			if p != "" {
				fmt.Fprintf(&o, "    \"%s\": allow\n", p)
			}
		}
	} else {
		o.WriteString("permission:\n  edit: allow\n")
	}
	o.WriteString("---\n" + head)
	out["adapters/opencode/agents/"+r.Name+".md"] = o.String()
	return nil
}

// Write renders into root, overwriting generated files.
func Write(root string) (int, error) {
	out, n, err := Build(root)
	if err != nil {
		return 0, err
	}
	for rel, c := range out {
		p := filepath.Join(root, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			return 0, err
		}
		if err := os.WriteFile(p, []byte(c), 0o644); err != nil {
			return 0, err
		}
	}
	return n, nil
}

// Check compares the rendered files with the tree and returns one line per
// out-of-date directory, each with the first difference found.
func Check(root string) ([]string, int, error) {
	out, n, err := Build(root)
	if err != nil {
		return nil, 0, err
	}
	var drift []string
	for _, d := range Dirs {
		first := ""
		have := map[string]bool{}
		_ = filepath.WalkDir(filepath.Join(root, filepath.FromSlash(d)), func(p string, e os.DirEntry, err error) error {
			if err == nil && !e.IsDir() {
				rel, _ := filepath.Rel(root, p)
				have[filepath.ToSlash(rel)] = true
			}
			return nil
		})
		var rels []string
		for rel := range out {
			if rel == d || strings.HasPrefix(rel, d+"/") {
				rels = append(rels, rel)
			}
		}
		for rel := range have {
			if _, ok := out[rel]; !ok {
				rels = append(rels, rel)
			}
		}
		sort.Strings(rels)
		for _, rel := range rels {
			want, gen := out[rel]
			b, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
			switch {
			case !gen:
				first = rel + ": not generated (stale file)"
			case err != nil:
				first = rel + ": missing"
			case string(b) != want:
				first = rel + ": " + firstDiff(string(b), want)
			}
			if first != "" {
				break
			}
		}
		if first != "" {
			drift = append(drift, "out of date: "+d+" ("+first+"); run sdkit dev adapters")
		}
	}
	return drift, n, nil
}

func firstDiff(have, want string) string {
	h, w := strings.Split(have, "\n"), strings.Split(want, "\n")
	for i := 0; i < len(h) || i < len(w); i++ {
		var a, b string
		if i < len(h) {
			a = h[i]
		}
		if i < len(w) {
			b = w[i]
		}
		if i >= len(h) || i >= len(w) || a != b {
			return fmt.Sprintf("line %d differs: committed %q, generated %q", i+1, a, b)
		}
	}
	return "differs"
}
